"""Write reports/doc_type/licensing_and_collection/licensing_decisions.{json,md} and in_financial_verification.json. Evidence strings were read from the primary pages on 2026-10-19 (see 'evidence'); file counts are recomputed from disk and the manifest at run time. No downloads."""
import json, collections
from pathlib import Path
from PIL import Image
ROOT = Path(__file__).resolve().parents[2]; D = ROOT / "reports/doc_type/licensing_and_collection"; DS = ROOT / "datasets"
def dec(src, url, terms, commercial, train_eval, redistribution, decision, needed, level, evidence): return dict(source=src, primary_url=url, exact_terms=terms, commercial_use=commercial, training_and_evaluation=train_eval, redistribution=redistribution, decision=decision, exact_permission_needed=needed, evidence_level=level, evidence=evidence)
rows = [
 dec("in_financial", "https://www.kaggle.com/datasets/mehaksingal/personal-financial-dataset-for-india", "Kaggle licence field: 'Database: Open Database, Contents: Database Contents' (ODbL 1.0 for the database; DbCL 1.0 for the contents)", "not established: DbCL s.2.1 grants a copyright licence over the Contents but s.3.1 provides them 'as is' without any warranty ... of title; the uploader does not claim to own the images",
     "academic research / ML training / evaluation: NOT established for the images (title unverified); only the uploader's database rights are licensed", "ODbL share-alike and attribution would apply to a public derived database; redistribution of third-party images not established",
     "BLOCKED (kept excluded)", "A written statement from the uploader (Kaggle user 'Mia') that she owns or may license the images, or per-image licences / issuer permission; and confirmation that none shows a real person's data. Alternative: keep only verified blank specimens/templates and treat them as non-evaluation data.", "primary_verified",
     ["Kaggle page 'Financial Document Image Dataset' (owner Mia, updated 3 years ago): description says it holds 'personal financial and identification documents for individuals in India'", "Kaggle Provenance: 'These images were collected from Google Images ... keyword searches ... 'utility bill template', 'bank statement example'' - no ownership claim", "opendatacommons.org DbCL 1.0 s.2.1 / s.2.3 / s.3.1 (as quoted)", "visual check of 12 random Salary/Form 16/Bank images: web specimens and templates with third-party brand names, a US-style 'Finance Bank' statement, a company balance sheet filed as bank statement, a blank ITR-2 filed as Form 16 - label noise and doubtful 'real' status"]),
 dec("sroie", "https://rrc.cvc.uab.es/?ch=13&com=downloads", "RRC challenge pages: registration required to access the downloads; no data terms shown. HF mirror jsdnrs/ICDAR2019-SROIE: licence field 'cc-by-4.0' (the arXiv paper 2103.10213 is itself CC-BY)", "unknown", "unknown until the RRC terms are seen", "unknown", "REQUIRES CLARIFICATION (kept excluded)", "The RRC portal terms of use accepted at registration (or written confirmation from the organisers) stating training/evaluation use; a mirror's CC-BY marking is not the data owner's licence.", "primary_verified (absence of terms)", ["rrc.cvc.uab.es downloads + introduction pages read", "HF card licence field", "github.com/zzzDavid/ICDAR-2019-SROIE: MIT covers the code only; no data licence"]),
 dec("funsd", "https://guillaumejaume.github.io/FUNSD/work/", "'Use of the FUNSD Dataset is solely for non-commercial, research and educational purposes.' Original images are part of RVL-CDIP; users must determine what further clearances are needed", "NOT permitted", "permitted for non-commercial research and education (training, evaluation)", "not granted", "APPROVED - non-commercial research only (tier 2)", "none for research use; commercial use or redistribution would need EPFL-LTS5 and the RVL-CDIP rights holders.", "primary_verified", ["FUNSD licence page (EPFL-LTS5 terms) read", "199 forms, no document-type labels: usable only as class 'other'"]),
 dec("hf_medical", "https://huggingface.co/datasets/destryet/medical_bills", "no licence, no dataset card, no provenance or redaction statement (destryet/medical_bills: 15 PDFs; mirror sansverse/medical-bill-samples: 17 PDFs, also none)", "unknown", "unknown", "unknown", "BLOCKED (kept excluded)", "Written permission from the uploader or the issuing hospital/pharmacy, and confirmation that the bills are anonymised.", "primary_verified (absence of terms)", ["both HF pages read: no licence field, no card"]),
 dec("user_real", "(user-supplied; no URL)", "198 US restaurant receipts; origin and rights unverified", "unknown", "unknown", "unknown", "REQUIRES CLARIFICATION (kept excluded)", "Owner attestation that the receipts were collected by the owner and may be used for ML training/evaluation, and that no personal card data is visible.", "unverified", ["project record only"]),
 dec("receiptbench", "https://huggingface.co/datasets/T0rl/ReceiptBench", "HF licence field 'mit'; README empty - no statement of image provenance, consent or personal data", "not established", "not established beyond the repo licence label", "not established", "REQUIRES CLARIFICATION (approval withdrawn on new evidence)", "Uploader statement of image provenance and consent, or per-image licences.", "primary_verified (absence of terms)", ["HF page read 2026-10-19: licence 'mit', README empty; earlier approval in approved-sources-v1 was based on the repo label alone"]),
 dec("manual_in", "(project owner collection)", "owner-collected Indian bills; rights unverified for third-party content", "unknown", "internal development only (owner's own collection)", "none", "APPROVED - internal development only (tier 2, unchanged)", "Owner attestation recorded in the consent register that no third-party personal data is retained.", "project_record", ["unchanged from approved-sources-v1; attestation still outstanding"]),
 dec("rvl_cdip", "https://huggingface.co/datasets/aharley/rvl_cdip", "HF licence field 'other' (IIT-CDIP derivative; research use)", "not permitted", "research use", "not granted", "APPROVED - research only (tier 2, unchanged)", "none for research use", "primary_verified", ["HF card licence field (register entry, 2026-10-19)"]),
 dec("docile", "https://docile.rossum.ai/", "code MIT; data via access-request form, academic purposes", "restricted", "academic purposes after approval of the request", "no", "BLOCKED (no access granted)", "Approved access request (needs a human applicant and acceptance of the terms).", "primary_verified (earlier round)", ["register evidence"]),
 dec("nutrient_doc_cls", "https://huggingface.co/datasets/nutrientdocs/document-classification-benchmark", "licence 'nutrient-eval-restricted'", "restricted", "evaluation-restricted", "no", "BLOCKED", "Written terms permitting our use.", "primary_verified (earlier round)", ["register evidence"]),
 dec("kaggle_roboflow_zindi", "(account-gated platforms)", "per dataset; account and acceptance of terms required", "per dataset", "per dataset", "per dataset", "BLOCKED (not accessed)", "A human with an account must read each dataset's terms; none selected.", "unverified", ["register evidence"]),
]
(D / "licensing_decisions.json").write_text(json.dumps(dict(decided="2026-10-19", note="record of what primary sources state; not legal advice", decisions=rows), indent=1))
md = ["# Licensing decisions (2026-10-19)\n\nEvidence read from primary pages; not legal advice. 'Approved' means approved for internal, non-commercial ML research only; no source permits redistribution of raw data.\n", "| source | decision | terms found (primary source) | commercial | training / evaluation | redistribution | exact permission needed |", "|---|---|---|---|---|---|---|"]
for r in rows: md.append("| {source} | **{decision}** | {exact_terms} ([source]({primary_url})) | {commercial_use} | {training_and_evaluation} | {redistribution} | {exact_permission_needed} |".format(**{k: str(v).replace("|", "/") for k, v in r.items()}))
(D / "licensing_decisions.md").write_text("\n".join(md) + "\n")
# in_financial verification
root = DS / "public/in_financial_docs"; disk = {}; bad = collections.Counter()
for d in sorted(root.iterdir()):
    fs = [f for f in d.iterdir() if f.is_file()]; disk[d.name] = len(fs)
    for f in fs:
        try: Image.open(f).verify()
        except Exception: bad[d.name] += 1
m = [json.loads(l) for l in open(DS / "metadata/doc_type_manifest_v2_1.jsonl")]; ins = [r for r in m if r["source"] == "in_financial"]
cls = collections.defaultdict(lambda: collections.Counter())
for r in ins: cls[r["original"].get("subcategory") or "Utility"][r["split"]] += 1
rep = dict(kaggle_listed_files=426, files_on_disk=disk, files_on_disk_total=sum(disk.values()), undecodable=dict(bad), manifest_rows=len(ins), after_dedup_by_class={k: dict(v, total=sum(v.values())) for k, v in cls.items()}, approved_for_training=sum(r["approved_for_training"] for r in ins),
           claimed_in_previous_audit=dict(salary_slip=89, form_16=37, bank_statement=85, cheque=92), counts_confirmed=all(sum(cls[k].values()) == v for k, v in dict(**{"Salary Slip": 89, "ITR_Form 16": 37, "Bank Statement": 85, "Check": 92}).items()),
           usable_even_if_cleared=dict(note="val/test supports would still be below 30 per class, so no per-class real metric could be reported from this source alone", val_test_support={k: dict(val=v["val"], test=v["test"]) for k, v in cls.items()}),
           quality_findings=["web specimens/templates (Google Images keyword search), not verified real filled documents", "third-party brand names visible", "country of origin mixed/unverified (bank statements include US-style templates)", "label noise seen in a 12-image visual check (balance sheet as bank statement, blank ITR-2 as Form 16)"], decision="blocked: not approved")
(D / "in_financial_verification.json").write_text(json.dumps(rep, indent=1)); print(json.dumps(rep, indent=1)[:1800])
